WITH unpacked AS (SELECT id, currency, tier_limits, discounts, ARRAY_MIN(tier_prices) AS lowest_price, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices FROM price_tiers WHERE currency IN ('USD', 'THB', 'EUR')) SELECT id, currency, tier_limits, discounts, lowest_price, net_prices, SUM(lowest_price) OVER (PARTITION BY currency ORDER BY lowest_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_lowest_price, FIRST_VALUE(lowest_price) IGNORE NULLS OVER (ORDER BY lowest_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_lowest_price, CUME_DIST() OVER (PARTITION BY currency ORDER BY lowest_price NULLS LAST) AS lowest_price_cume_dist, PERCENT_RANK() OVER (ORDER BY lowest_price DESC NULLS FIRST) AS lowest_price_percent_rank FROM unpacked;
